CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('admin','caseworker','accountant','viewer');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text UNIQUE NOT NULL,display_name text NOT NULL,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'viewer',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE families(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_number text UNIQUE NOT NULL,family_surname text NOT NULL,head_name text NOT NULL,head_national_id text UNIQUE NOT NULL CHECK(head_national_id ~ '^\d{10}$'),head_birth_date text,head_phone text NOT NULL,family_phone text,head_education jsonb NOT NULL DEFAULT '{}',head_job text,insurance jsonb NOT NULL DEFAULT '{}',housing_type text NOT NULL,housing_deposit bigint NOT NULL DEFAULT 0 CHECK(housing_deposit>=0),housing_rent bigint NOT NULL DEFAULT 0 CHECK(housing_rent>=0),address text,notes text,priority text NOT NULL DEFAULT 'متوسط',archived boolean NOT NULL DEFAULT false,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE family_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,name text NOT NULL,relation text,national_id text UNIQUE CHECK(national_id ~ '^\d{10}$'),birth_date text,education jsonb NOT NULL DEFAULT '{}',job text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE financial_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,title text NOT NULL,category text,status text NOT NULL,amount bigint NOT NULL CHECK(amount>0),jalali_year int,jalali_month int CHECK(jalali_month BETWEEN 1 AND 12),institution_note text,description text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,body text NOT NULL,status text,institution_note text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION deny_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_logs is append-only'; END $$;CREATE TRIGGER audit_no_update BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION deny_audit_mutation();
